expression:
local({
  hrs <- lapply(list(XTPTBWKDYMT, XTPOBWKDYMT), function(x) {
    x <- na_if(trimws(x), "")
    as.numeric(sub(":.*", "", x)) + as.numeric(sub(".*:", "", x)) / 60
  })
  (hrs[[2]] - hrs[[1]]) %% 24
})

local({
  hrs <- lapply(list(XTPTBWKNDMT, XTPOBWKNDMT), function(x) {
    x <- na_if(trimws(x), "")
    as.numeric(sub(":.*", "", x)) + as.numeric(sub(".*:", "", x)) / 60
  })
  (hrs[[2]] - hrs[[1]]) %% 24
})

local({
  hrs <- lapply(list(XTPTBWKDYMT, XTPOBWKDYMT, XTPTBWKNDMT, XTPOBWKNDMT), function(x) {
    x <- na_if(trimws(x), "")
    as.numeric(sub(":.*", "", x)) + as.numeric(sub(".*:", "", x)) / 60
  })
  (5 * ((hrs[[2]] - hrs[[1]]) %% 24) + 2 * ((hrs[[4]] - hrs[[3]]) %% 24)) / 7
})
